-- ═══════════════════════════════════════════════════════════════════════════
-- 00293 — Seed designer-onboarding email templates (Wave 3a)
--
-- Registers the 17 React Email templates in packages/email/src/templates/
-- (T0/N1/N2 invite track, W0/E2-E10 spine, M1-M4 milestones — see
-- docs/marketing/founding-onboarding/copy-deck.md) as email_templates rows.
-- render-template.ts (supabase/functions/_shared/render-template.ts) reads
-- these by slug and mustache-interpolates the literal {{var}} tokens baked
-- into html_content at send time — the tokens below are NOT resolved here.
--
-- Generated by packages/email/scripts/render-db-templates.ts via
-- `pnpm --filter @patina/email render:onboarding-templates`, which renders
-- each template through @react-email/render and prints this exact
-- INSERT ... ON CONFLICT (slug) DO UPDATE statement. Copy revisions: re-run
-- the script and ship the refreshed SQL as a NEW migration — this file is a
-- point-in-time snapshot, not a live template store.
--
-- Column shape: 00045_email_templates.sql (slug, name, description,
-- category email_template_category enum, subject_default, variables,
-- is_active) + 00051_email_templates_html_content.sql (html_content TEXT
-- NOT NULL DEFAULT ''). category follows the copy deck's own per-email
-- "track / category" line: 'transactional' for the 3 invite-track emails
-- (T0/N1/N2) + the 4 milestone emails (M1-M4); 'sequence' for the 10 spine
-- emails (W0, E2-E10) — the deck lists 10 track:spine/category:sequence
-- emails, not 9.
--
-- Values are dollar-quoted ($html$...$html$) rather than ''-escaped: the
-- rendered HTML and body copy are full of apostrophes (I've, you're,
-- designer's, ...) that would otherwise need escaping throughout — same
-- rationale as this codebase's existing dollar-quoted function bodies.
-- Idempotent: ON CONFLICT (slug) DO UPDATE (00284_field_dispatch_wiring.sql
-- proven pattern), is_active forced true on every re-run.
-- ═══════════════════════════════════════════════════════════════════════════

INSERT INTO public.email_templates
  (slug, name, description, category, subject_default, html_content, variables, is_active)
VALUES
  ($html$designer-invite$html$, $html$Designer Invite (T0)$html$, $html$Founding-designer invitation letter -- the first email in the invite track.$html$, $html$transactional$html$::email_template_category, $html$An invitation to Patina$html$, $html$<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.0 Transitional//EN" "http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd"><html dir="ltr" lang="en"><head><meta content="text/html; charset=UTF-8" http-equiv="Content-Type"/><meta name="x-apple-disable-message-reformatting"/><style>
